    public static function obtenerListadoDatRegistroSalario($idpersona, $idestructura, $start, $limit)
    {
        $query = new Doctrine_Query ();
        $result = (($start != null) and ($limit != null))?
        $query->from('DatRegistroSalarioTiempoServicio')
            ->where('idpersona = ?', array($idpersona))
            ->orderBy('idmes DESC')           
            ->limit($start)
            ->offset($limit)
            ->fetchArray():
            $query->from('DatRegistroSalarioTiempoServicio')
            ->where('idpersona = ?', array($idpersona))
            ->orderBy('idmes DESC')  
            ->fetchArray();

        return $result;
    }

