                            where idpersona = {$idpersona} 
                              and idestructura = {$idestructura} 
                              and anno <= {$annoPer} 
                              and (((anno||'-'||idmes||'-01')::date) >= (SELECT '{$strFechaInicio}'::date - INTERVAL '{$cantidad_meses} months') 
                              and ((anno||'-'||idmes||'-01')::date) < '{$strFechaInicio}'::date)
                            order by anno DESC, idmes DESC;";
                    $mg = Doctrine_Manager::getInstance();
                    $conn = $mg->getCurrentConnection();
                    return $conn->fetchAll($sql);
                    //Si tiene nominas configuradas el campo del reporte
                } else {
                    $sql = "select drs.idregistrosalariotiemposervicio, drs.idpersona, drs.anno, drs.idmes, drs.diasacumulados,  
                             (CASE WHEN drs.idtiponomina in ({$tiposnominas}) THEN drs.salariodevengado ELSE 0.00 END) as salariodevengado,  
                             drs.idtiponomina, drs.idestructura, drs.idconfregistsalartiempservc, drs.salariodevengadoreporte  
                            from mod_nomina.dat_registrosalariotiemposervcio drs 
                            where drs.idpersona = {$idpersona} 
                              and drs.idestructura = {$idestructura} 
                              and anno <= {$annoPer} 
                              and (((drs.anno||'-'||drs.idmes||'-01')::date) >= (SELECT '{$strFechaInicio}'::date - INTERVAL '{$cantidad_meses} months') 
                              and ((drs.anno||'-'||drs.idmes||'-01')::date) < '{$strFechaInicio}'::date)
                            order by drs.anno DESC, drs.idmes DESC;";
                    $mg = Doctrine_Manager::getInstance();
                    $conn = $mg->getCurrentConnection();
                    return $conn->fetchAll($sql);
                }
            }
        }else{
            //Si no tiene nominas configuradas el campo del reporte
            if ($tiposnominas == null || $tiposnominas == '') {
                $sql = "select * from mod_nomina.dat_registrosalariotiemposervcio 
