    public static function obtenerListadoDatRegistroSalarioRangoFechas($idestructura,$fechadesde, $fechahasta,$idtiponomina = null, $idpersona)
    {
        $tiponomina = ($idtiponomina != null)?" and dr.idtiponomina = $idtiponomina ":"";
        $sql = "select dr.*,ntn.denominacion as denomnomina from mod_nomina.dat_registrosalariotiemposervcio dr
        inner join mod_nomina.nom_tiponomina ntn on ntn.idtiponomina = dr.idtiponomina
        where ((dr.anno::text||'-'||dr.idmes::text||'-'||'1')::date between ('$fechadesde')::date and
        ('$fechahasta')::date) and dr.idpersona = $idpersona and dr.idestructura = $idestructura". $tiponomina . 
        "order by anno asc, idmes desc";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql);
    }

